export type DriftStatus = (typeof DRIFT_STATUSES)[number];
export type ResolutionDoc = Readonly<z.infer<typeof ResolutionDocSchema>>;
export type ResolutionIr = Readonly<z.infer<typeof ResolutionIrSchema>>;
